function marketplacePage(base, rows, requested) {
  const available = rows.filter(row => row.status === 'available');
  const cards = available.map(row => `<article class="card">${row.image_url ? `<img class="opportunity-image" src="${h(row.image_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">` : ''}<div class="eyebrow">${h(row.location)} · ${h(row.format)}</div><h2>${h(row.name)}</h2><p>${h(row.description)}</p><p><strong style="font-size:24px;color:var(--forest)">${h(row.display_price || `${money(row.annualPrice)}/year`)}</strong>${Number(row.estimated_impressions) > 0 ? `<br>${Number(row.estimated_impressions).toLocaleString()} estimated annual impressions` : ''}</p><form method="post" action="${base}/marketplace/request"><input type="hidden" name="inventoryId" value="${row.id}"><input name="advertiserName" value="Demo Advertiser" aria-label="Advertiser name" required><input name="contactName" value="Demo User" aria-label="Contact name" required><input type="email" name="contactEmail" value="demo@example.invalid" aria-label="Contact email" required><button class="btn" type="submit">Request this opportunity</button></form></article>`).join('');
  return shell({ title:'Opportunity Marketplace', heading:'Available advertising and sponsorship opportunities', eyebrow:'Vivid Marketplace', subtitle:'Explore availability, audience, published pricing and measurable value.', base, content:`${requested?'<div class="notice"><strong>Demo request recorded.</strong> Open Advertising Requests in the organization portal to review it.</div>':''}<div class="market">${cards}</div>`, nav:'', portalLinks:true });
}

function advertiserSelector(base, path, advertisers, selected, from = '', to = '') {
  const a = selected || advertisers[0];
  return `<form class="inline" method="get" action="${base}/${path}"><label><strong>Demo advertiser</strong><br><select name="advertiser_id" onchange="this.form.submit()">${advertisers.map(row=>`<option value="${row.id}"${Number(row.id)===Number(a.id)?' selected':''}>${h(row.name)}</option>`).join('')}</select></label>${from ? `<input type="hidden" name="from" value="${h(from)}"><input type="hidden" name="to" value="${h(to)}">` : ''}</form>`;
}

function campaignTotals(campaigns) {
  return campaigns.reduce((result, row) => ({
    scans: result.scans + Number(row.scans),
    clicks: result.clicks + Number(row.clicks),
    conversions: result.conversions + Number(row.conversions),
    revenue: result.revenue + Number(row.revenue),
    investment: result.investment + Number(row.investment)
  }), { scans: 0, clicks: 0, conversions: 0, revenue: 0, investment: 0 });
}

function advertiserSetupPage(base, advertisers, selected, campaigns) {
  const a = selected || advertisers[0];
  const body = campaigns.map(row => `<tr><td><a href="${base}/organization/campaign/${row.campaign_id}">${h(row.campaign)}</a></td><td><a href="${base}/organization/placement/${row.inventory_id}">${h(row.placement)}</a><br><small>${h(row.location)}</small></td><td>${h(row.destination_url)}</td><td>${date(row.starts_on)} → ${date(row.ends_on)}</td><td>${status(row.status)}</td></tr>`).join('');
  return shell({ title:'My Setup', nav:advertiserNav(base,'setup',a.id), heading:'My Setup', eyebrow:'Vivid Advertiser', subtitle:`Locations, placements, QR tracking, campaigns, assignments and schedules for ${a.name}.`, base, content:`${advertiserSelector(base,'advertiser/setup',advertisers,a)}<div class="grid metrics">${metric('Locations',new Set(campaigns.map(x=>x.location)).size,'')}${metric('Placements',new Set(campaigns.map(x=>x.inventory_id)).size,'')}${metric('Campaigns',campaigns.length,'')}${metric('Active assignments',campaigns.filter(x=>x.status==='active').length,'')}</div><section class="panel"><div class="section-head"><div><h2>Launch Checklist</h2><p>The same Vivid Core building blocks used by live advertiser accounts.</p></div></div><div class="grid"><article class="card"><h3>✓ Locations</h3><p>Advertising locations are connected.</p></article><article class="card"><h3>✓ Placements &amp; QR Codes</h3><p>Reusable tracking codes are assigned to placements.</p></article><article class="card"><h3>✓ Campaigns</h3><p>Destinations and conversion definitions are configured.</p></article><article class="card"><h3>✓ Assignments</h3><p>Campaigns are connected to exact placements.</p></article><article class="card"><h3>✓ Schedule</h3><p>Campaign terms and active timing are visible.</p></article></div></section><section class="panel"><h2>Campaign Assignments</h2><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Placement</th><th>Destination</th><th>Schedule</th><th>Status</th></tr></thead><tbody>${body}</tbody></table></div></section>` });
}

function advertiserReportsPage(base, advertisers, selected, campaigns, from, to) {
  const a = selected || advertisers[0];
  const body = campaigns.map(row => `<tr><td><a href="${base}/organization/campaign/${row.campaign_id}">${h(row.campaign)}</a></td><td>${h(row.location)}</td><td><a href="${base}/organization/placement/${row.inventory_id}">${h(row.placement)}</a></td><td>${row.scans}</td><td>${row.clicks}</td><td>${row.conversions}</td><td>${money(row.revenue)}</td><td>${row.roi}%</td></tr>`).join('');
  return shell({ title:'Reports', nav:advertiserNav(base,'reports',a.id), heading:'Reports', eyebrow:'Vivid Advertiser', subtitle:'Date-filtered reporting by campaign, placement, engagement, conversion, revenue and ROI.', base, content:`${advertiserSelector(base,'advertiser/reports',advertisers,a,from,to)}${dateFilter(`${base}/advertiser/reports`,from,to,`advertiser_id=${a.id}`)}<section class="panel"><div class="section-head"><div><h2>Campaign Reports</h2><p>Every result drills back to its campaign and placement.</p></div><a class="btn" href="${base}/exports/performance.csv?advertiser_id=${a.id}&from=${from}&to=${to}">Export CSV</a></div><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Location</th><th>Placement</th><th>Scans</th><th>Actions</th><th>Conversions</th><th>Revenue</th><th>ROI</th></tr></thead><tbody>${body}</tbody></table></div></section>` });
}

function advertiserPerformancePage(base, advertisers, selected, campaigns, from, to) {
  const a = selected || advertisers[0];
  const totals = campaignTotals(campaigns);
  const best = [...campaigns].sort((x,y)=>Number(y.revenue)-Number(x.revenue))[0];
  return shell({ title:'Performance Insights', nav:advertiserNav(base,'performance',a.id), heading:'Performance Insights', eyebrow:'Vivid Advertiser', subtitle:'Executive scorecard using the same attribution hierarchy as Vivid Core.', base, content:`${advertiserSelector(base,'advertiser/performance',advertisers,a,from,to)}${dateFilter(`${base}/advertiser/performance`,from,to,`advertiser_id=${a.id}`)}<div class="grid metrics">${metric('Scans',totals.scans,'')}${metric('Website actions',totals.clicks,'')}${metric('Conversions',totals.conversions,'')}${metric('Attributed revenue',money(totals.revenue),'')}${metric('Advertising investment',money(totals.investment),'')}${metric('ROI',`${totals.investment?Math.round((totals.revenue-totals.investment)/totals.investment*100):0}%`,'')}</div><div class="compare"><article class="card after"><span class="sample">Top performer</span><h2>${h(best?.campaign || 'No campaign activity')}</h2><p>${best ? `${money(best.revenue)} attributed revenue and ${best.conversions} conversions from ${best.placement}.` : 'No performance is available for this range.'}</p>${best?`<a class="btn" href="${base}/organization/campaign/${best.campaign_id}">Open Campaign</a>`:''}</article><article class="card before"><span class="sample">Needs attention</span><h2>Conversion coverage</h2><p>${campaigns.some(row=>Number(row.clicks)>0&&!Number(row.conversions))?'At least one campaign has engagement without a confirmed conversion.':'All active sample campaigns have confirmed conversions in this range.'}</p></article></div>` });
}

